// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RelaySite) predicate.RelaySite {
	return predicate.RelaySite(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RelaySite) predicate.RelaySite {
	return predicate.RelaySite(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RelaySite) predicate.RelaySite {
	return predicate.RelaySite(sql.NotPredicates(p))
}
